  let db; try { db = { ...blank(), ...JSON.parse(localStorage.getItem(KEY) || '{}') }; } catch { db = blank(); }
  let page = 'dashboard', modal = null, examRun = null, flashRun = null, searchText = '', filters = { type: 'all', subject: 'all' }, toastTimer, importDraft = { raw: '', questions: [], subjectId: '', topic: '', type: 'auto', hash: '', duplicate: false };
  const $ = (s, r = document) => r.querySelector(s), $$ = (s, r = document) => [...r.querySelectorAll(s)], esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const uid = () => Math.random().toString(36).slice(2, 10), save = () => localStorage.setItem(KEY, JSON.stringify(db)), today = () => new Date().toISOString().slice(0, 10), fmtDate = s => new Date(s).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
  function touch() { const t = today(); if (db.lastStudy !== t) { let y = new Date(); y.setDate(y.getDate() - 1); db.streak = db.lastStudy === y.toISOString().slice(0, 10) ? (db.streak || 0) + 1 : 1; db.lastStudy = t; } db.activity.unshift({ date: new Date().toISOString(), text: 'Studied in Studyroom' }); db.activity = db.activity.slice(0, 30); save(); }
