  const nav = [['dashboard', '⌂', 'Dashboard'], ['subjects', '▦', 'My Subjects'], ['questions', '☷', 'Question Bank'], ['smart-import', '⇧', 'Smart Import'], ['create-exam', '＋', 'Create Exam'], ['exams', '▤', 'My Exams'], ['flashcards', '▱', 'Flashcards'], ['mistakes', '↗', 'My Mistakes'], ['statistics', '◌', 'Statistics'], ['settings', '⚙', 'Settings']];
